import type { Metadata } from "next";
import { FIRM } from "./site";

// Generated by app/opengraph-image.tsx and app/twitter-image.tsx. A page that sets its own
// openGraph/twitter fields replaces the inherited image, so it is referenced explicitly here.
const OG_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: "Hartford, CT Immigration Lawyer: Law Office of Jacquelyn R. Goncalves" };

/**
 * Per-page metadata with canonical, Open Graph and Twitter tags kept in sync.
 * Keep titles ≤ 60 characters and descriptions ≤ 155 so search results don't truncate them.
 */
export function pageMeta({ title, description, path }: { title: string; description: string; path: string }): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { type: "website", locale: "en_US", siteName: FIRM, title, description, url: path, images: [OG_IMAGE] },
    twitter: { card: "summary_large_image", title, description, images: ["/twitter-image"] },
  };
}
